  })
}

/** The button that picks the columns a test list shows, for every list in the report. */
function ColumnPicker({ chosen, onChange, available }: { chosen: string[]; onChange: (keys: string[]) => void; available: Column[] }) {
  const [open, setOpen] = useState(false)
  const root = useRef<HTMLDivElement>(null)
  useEffect(() => {
    if (!open) return
    const away = (e: MouseEvent) => { if (!root.current?.contains(e.target as Node)) setOpen(false) }
    const esc = (e: KeyboardEvent) => { if (e.key === "Escape") { e.stopPropagation(); setOpen(false); root.current?.querySelector("button")?.focus() } }
    document.addEventListener("mousedown", away)
    document.addEventListener("keydown", esc, true)
    return () => { document.removeEventListener("mousedown", away); document.removeEventListener("keydown", esc, true) }
  }, [open])
  const toggle = (key: string, on: boolean) => onChange(COLUMNS.filter((c) => !c.fixed && (c.key === key ? on : chosen.includes(c.key))).map((c) => c.key))
  return (
    <div className="mt-cols" ref={root}>
      <button type="button" className="mt-cols-btn" aria-haspopup="true" aria-expanded={open} onClick={() => setOpen((o) => !o)} title="Choose columns">
        <Icon name="columns" /><span className="mt-sr">Columns</span>
      </button>
      {open && (
        <div className="mt-cols-list" role="group" aria-label="Columns">
          <div className="mt-cols-h">Columns</div>
          {available.map((c) => (
            <label key={c.key}>
              <input type="checkbox" checked={chosen.includes(c.key)} onChange={(e) => toggle(c.key, (e.target as HTMLInputElement).checked)} />{c.label}
            </label>
          ))}
          <button type="button" className="mt-cols-reset" onClick={() => onChange(STANDARD_COLUMNS)}>Reset to default</button>
        </div>
      )}
    </div>
  )
}

